// src/lib/ontology/graph.ts
var buildEdges = () => {
  const edges = [];
  for (const e of ONTOLOGY.entities) {
    for (const r of e.relations ?? []) {
      edges.push({ from: e.name, to: r.target, via: r.via });
      edges.push({ from: r.target, to: e.name, via: r.via });
    }
  }
  return edges;
};
var EDGES = buildEdges();

