import { defineTool as defineTool3 } from "npm:@lovable.dev/mcp-js@0.20.1";
import { z as z3 } from "npm:zod@^3.25.76";
var ingest_knowledge_default = defineTool3({
  name: "ingest_knowledge",
  title: "Ingest knowledge chunks",
  description: "Add one or more knowledge chunks (ontology notes, defect summaries, test cases, Q&A) to the DTSV RAG index. Content is embedded and stored for future hybrid search.",
  inputSchema: {
    items: z3.array(
      z3.object({
        source_type: z3.enum(["ontology", "defect", "testcase", "qa_history", "qa_negative"]),
        source_id: z3.string().min(1),
        title: z3.string().optional(),
        content: z3.string().min(1),
        metadata: z3.record(z3.string(), z3.unknown()).optional()
      })
    ).min(1).max(50)
  },
  annotations: { readOnlyHint: false, destructiveHint: false, idempotentHint: false },
  handler: async ({ items }) => {
    const supabaseUrl = process.env.SUPABASE_URL;
    const anonKey = process.env.SUPABASE_PUBLISHABLE_KEY ?? process.env.SUPABASE_ANON_KEY;
    const resp = await fetch(`${supabaseUrl}/functions/v1/embed-knowledge`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${anonKey}`
      },
      body: JSON.stringify({ items })
    });
    const data = await resp.json();
    if (!resp.ok) {
      return {
        content: [{ type: "text", text: data?.error ?? `embed-knowledge failed (${resp.status})` }],
        isError: true
      };
    }
    return {
      content: [{ type: "text", text: `Inserted ${data.inserted} rows (${data.chunks} chunks) in ${data.embed_ms}ms.` }],
      structuredContent: data
    };
  }
});

